using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IAsyncLifetime
{
    private readonly HttpListener listener = new();
    private readonly HttpClient client;
    private readonly string baseUrl;
    private Task serving = Task.CompletedTask;

    private string? method;
    private string? path;
    private string? contentType;
    private string? body;
    private int replyStatus = 200;
    private string replyBody = "{}";

    public HttpPaymentGatewayTests()
    {
        var probe = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
        probe.Start();
        var port = ((IPEndPoint)probe.LocalEndpoint).Port;
        probe.Stop();

        baseUrl = $"http://127.0.0.1:{port}/";
        listener.Prefixes.Add(baseUrl);
        client = new HttpClient { BaseAddress = new Uri(baseUrl) };
    }

    public Task InitializeAsync()
    {
        listener.Start();
        serving = Task.Run(async () =>
        {
            while (listener.IsListening)
            {
                HttpListenerContext ctx;
                try { ctx = await listener.GetContextAsync(); }
                catch { return; }

                method = ctx.Request.HttpMethod;
                path = ctx.Request.Url!.AbsolutePath;
                contentType = ctx.Request.ContentType;
                using (var reader = new StreamReader(ctx.Request.InputStream, Encoding.UTF8))
                    body = await reader.ReadToEndAsync();

                ctx.Response.StatusCode = replyStatus;
                ctx.Response.ContentType = "application/json";
                var bytes = Encoding.UTF8.GetBytes(replyBody);
                await ctx.Response.OutputStream.WriteAsync(bytes);
                ctx.Response.Close();
            }
        });
        return Task.CompletedTask;
    }

    public async Task DisposeAsync()
    {
        listener.Close();
        await serving;
        client.Dispose();
    }

    private Task<AuthorizationOutcome> Authorize(string reference = "ORD-7", decimal amount = 12.50m, string currency = "eur") =>
        new HttpPaymentGateway(client).AuthorizeAsync(reference, new Money(amount, currency), CancellationToken.None);

    [Fact]
    public async Task The_request_is_a_json_post_to_the_authorizations_endpoint()
    {
        replyBody = """{"status":"approved"}""";

        await Authorize();

        Assert.Equal("POST", method);
        Assert.Equal("/v1/authorizations", path);
        Assert.StartsWith("application/json", contentType);
    }

    [Fact]
    public async Task The_request_body_carries_reference_amount_and_normalized_currency()
    {
        replyBody = """{"status":"approved"}""";

        await Authorize("ORD-7", 12.50m, "eur");

        using var json = JsonDocument.Parse(body!);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_status_is_read_as_approved()
    {
        replyBody = """{"status":"approved"}""";

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        replyBody = """{"id":"auth_1","status":"approved","risk":{"score":3}}""";

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_status_is_read_as_declined()
    {
        replyBody = """{"status":"declined"}""";

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task An_unrecognised_status_is_never_treated_as_approved()
    {
        replyBody = """{"status":"pending"}""";

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task An_answer_without_a_status_is_never_treated_as_approved()
    {
        replyBody = """{"result":"approved"}""";

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_is_a_decline_even_if_the_body_says_approved()
    {
        replyStatus = 402;
        replyBody = """{"status":"approved"}""";

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_with_an_empty_body_is_a_decline()
    {
        replyStatus = 402;
        replyBody = "";

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failures_surface_as_errors_not_as_declines(int status)
    {
        replyStatus = status;
        replyBody = """{"status":"approved"}""";

        var error = await Assert.ThrowsAsync<HttpRequestException>(() => Authorize());
        Assert.Equal((HttpStatusCode)status, error.StatusCode);
    }

    [Fact]
    public async Task A_malformed_answer_surfaces_as_an_error()
    {
        replyBody = "not json";

        await Assert.ThrowsAsync<JsonException>(() => Authorize());
    }
}
